insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 1, 'The peerReview engine groups some comment statuses as resolved, meaning nobody still has to act. Which statuses are in that group?', '["\"Closed\" and \"Withdrawn\", the two statuses with no legal move out of them.", "\"Verified\", \"Closed\" and \"Rejected\", every status a reviewer or coordinator has set.", "\"Verified\", \"Closed\" and \"Withdrawn\".", "\"Responded\", \"Verified\" and \"Closed\"."]'::jsonb, 2, 'Resolved is wider than final. "Verified" is resolved because the reviewer has accepted the response, although the coordinator still has the move to "Closed" to make. "Rejected" waits on the author and "Responded" waits on the reviewer, so neither is resolved.'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 2, 'With six comment statuses there are 36 ordered pairs of a status and a status to move to. How many of those pairs does the engine hold as legal moves?', '["7, which are exactly the entries of the legal-move table in the engine.", "6, one legal move out of each of the six statuses.", "12, two legal moves out of each of the six statuses in turn.", "9, because \"Open\", \"Responded\" and \"Rejected\" have two exits each and \"Verified\" has three."]'::jsonb, 0, '"Closed" and "Withdrawn" have no exit at all. "Open" and "Rejected" each have two, "Responded" has two and "Verified" has one: 2 + 2 + 2 + 1 gives the 7 legal moves the digest counts.'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 3, 'A comment is "Open". Which statuses may it legally move to next?', '["\"Responded\" or \"Verified\", both by the reviewer who raised it.", "\"Responded\", \"Withdrawn\" or \"Closed\", the last by the coordinator.", "\"Withdrawn\" only, because the author answers from \"Rejected\".", "\"Responded\", by the author, or \"Withdrawn\", by the reviewer."]'::jsonb, 3, 'The open comment waits on the author, whose move is "Responded". The reviewer may also take it back to "Withdrawn". Anything else is refused with "An open comment can only go to Responded or Withdrawn."'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 4, 'In the comment loop, which role makes the move from "Verified" to "Closed"?', '["The reviewer, as the last of the reviewer''s own moves on the comment.", "The coordinator, who runs the review and records that the comment is finished.", "The author, once the reviewer has accepted the author''s response to it.", "Nobody, because a verified comment is already final."]'::jsonb, 1, 'TRANSITION_ACTOR gives "Closed" to the coordinator. It is administrative: the reviewer has already accepted the response by verifying it, and closing records that the comment is finished with.'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 5, 'A comment reads "Responded" but carries no response text. A reviewer asks the engine to move it to "Verified". What comes back?', '["The move is allowed, because \"Verified\" is a legal next status from \"Responded\".", "A refusal: \"A comment cannot be verified before the author has responded to it.\"", "A refusal: \"A responded comment can only go to Verified or Rejected.\"", "A refusal: \"This comment is already responded.\""]'::jsonb, 1, 'The status and the response text are two fields, and the move to "Verified" checks the text as well. Verifying is a judgement about a response, so a response has to exist before there is anything to verify.'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 6, 'A comment row arrives with no status at all, and somebody asks for it to be moved to "Closed". How does the engine answer?', '["It reads the comment as finished and allows the move, since nothing is left to act on.", "It refuses with \"A closed comment is final.\", because a missing status is read as closed.", "It refuses with \"Sign in to act on this comment.\"", "It treats the missing status as the start of the loop and refuses the shortcut, as it would for any comment still waiting on its author."]'::jsonb, 3, 'The engine does not guess that a statusless comment is done. It treats the row as the start of the loop, where somebody still has to act, and the shortcut to "Closed" gets the sentence any open comment gets: "An open comment can only go to Responded or Withdrawn."'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 7, 'A reviewer has just rejected the author''s response to a comment. Where can that comment go from here?', '["\"Responded\" or \"Withdrawn\".", "\"Verified\" or \"Withdrawn\".", "\"Open\" or \"Responded\".", "None: \"Rejected\" is final."]'::jsonb, 0, 'A rejected comment goes back to the author, who responds again, and the reviewer may still withdraw it. The loop turns until the reviewer verifies a response or withdraws the comment.'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 8, 'Which comment status is resolved and still has a legal move left?', '["\"Withdrawn\", which a reviewer can still reopen to \"Open\" if the comment returns.", "\"Responded\", which the reviewer can still verify or reject.", "\"Verified\", which can still go to \"Closed\".", "\"Closed\", which the coordinator can hand back."]'::jsonb, 2, 'The resolved set is "Verified", "Closed" and "Withdrawn". The last two are final. "Verified" needs nobody to judge it any more, so it stops holding a review open, and the coordinator still has the step to "Closed".'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 9, 'A reviewer tries to move an "Open" comment straight to "Verified". Which sentence does the engine return?', '["\"A comment cannot be verified before the author has responded to it.\"", "\"This comment is already open.\"", "\"The author of the work under review cannot verify a comment on it.\"", "\"An open comment can only go to Responded or Withdrawn.\""]'::jsonb, 3, 'The move is illegal from the current status, so the refusal lists the legal targets. Reading it, the reviewer learns that the author has to answer first. The no-response-text sentence belongs to a comment whose status already reads "Responded".'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 10, 'A coordinator asks the engine to move a "Closed" comment to "Closed" again. What is the answer?', '["A refusal: \"This comment is already closed.\"", "A refusal: \"A closed comment is final.\"", "The move is allowed, and the record is left exactly as it was before the request.", "A refusal: \"A verified comment can only go to Closed.\""]'::jsonb, 0, 'A move to the status a comment already holds has its own family of sentences. Every other move out of "Closed" reads "A closed comment is final.", and the same-status request is the one exception in wording.'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 11, 'A "Withdrawn" comment is asked to move to "Responded". Which sentence comes back?', '["\"A withdrawn comment can only go to Responded or Withdrawn.\"", "\"A withdrawn comment is final.\"", "\"This comment is already withdrawn.\"", "\"An open comment can only go to Responded or Withdrawn.\""]'::jsonb, 1, '"Withdrawn" has no legal next status, so the refusal names no way forward because there is none. The same-status sentence is reserved for a move from "Withdrawn" to "Withdrawn".'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 12, 'The comment refusals fall into three families. Which family tells the user the comment has no legal move left at all, and why?', '["Moves to the status a comment already holds, because nothing needed doing on the record.", "Moves illegal from the current status, since those sentences only say that the move is refused.", "Moves out of \"Closed\" or \"Withdrawn\", because a final status has no legal move to name.", "Moves asked with nobody signed in, because no actor exists to be shown the way."]'::jsonb, 2, 'Illegal moves list their legal targets, and same-status requests say the comment is already there. "A closed comment is final." and "A withdrawn comment is final." list nothing, because nothing is left.'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 13, 'A comment is "Rejected". On whom does it wait, and for what move?', '["The author, who can answer the comment again by responding to it.", "The reviewer, who has to verify the rejected response before the comment can move.", "The coordinator, who closes a rejected comment out.", "Nobody, since a rejection is the end of the loop."]'::jsonb, 0, 'Of the three unresolved statuses, "Open" and "Rejected" wait on the author and "Responded" waits on the reviewer. The author''s move from "Rejected" is "Responded", and each turn of the loop leaves a response behind it.'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 14, 'Both "Closed" and "Withdrawn" finish a comment. Which one records an answer that somebody accepted?', '["\"Withdrawn\", because the reviewer can only withdraw once satisfied.", "Both, since either one can only follow a response the reviewer accepted.", "Neither, since acceptance lives in the review stage.", "\"Closed\", reached after the reviewer verified the author''s response."]'::jsonb, 3, '"Withdrawn" is reachable from "Open", before the author has answered, and from "Rejected", after the reviewer refused an answer. Only the full loop through "Verified" to "Closed" carries an accepted response.'),
  ('riskchange', 'advanced', 'module', 'm01-the-comment-loop', 15, 'u-kemi, an independent reviewer, asks to respond to C-02 on IK-01, which is already "Verified". What does the engine return?', '["The move is allowed, because u-kemi is independent of the work.", "A refusal: \"A verified comment can only go to Closed.\"", "A refusal: \"This comment is already verified.\"", "A refusal: \"The author of the work under review cannot review it.\""]'::jsonb, 1, 'Independence answers who may take a reviewer''s move. The legal-move table answers which moves exist, and it refuses this one whoever asks, because the only way out of "Verified" is "Closed".'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 1, 'IK-01, Water injection pump selection, carries nine comments. Which of them block the review from closing?', '["C-01, C-02 and C-08.", "C-01, C-03 and C-04.", "C-01, C-06, C-07 and C-09.", "C-01 and C-03."]'::jsonb, 1, 'A comment blocks when its severity is "Critical" or "Major" and its status is unresolved. C-02 and C-08 are "Critical" and resolved. C-06, C-07 and C-09 are open and never block, being "Minor", "Editorial" and unrated. C-04 is "Major" and "Rejected", which is unresolved.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 2, 'C-04 on IK-01 is a "Major" comment whose status is "Rejected". Why does it still block?', '["A rejection drops the comment from the review, so it blocks only until it is closed out.", "Every \"Major\" comment blocks whatever its status, until the coordinator closes the review.", "The engine reads a \"Rejected\" comment as \"Critical\" once the reviewer has refused a response to it.", "\"Rejected\" is unresolved: the reviewer did not accept the author''s response."]'::jsonb, 3, 'The resolved statuses are "Verified", "Closed" and "Withdrawn". "Rejected" is not among them, so a "Major" comment in that status is both blocking in severity and unresolved in status. C-05 is "Major" too and does not block, because it is "Withdrawn".'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 3, 'The coordinator asks the engine to close IK-01 as it stands. What comes back?', '["A refusal: \"1 critical and 2 major comments still need resolving. Verify, close out or withdraw them first.\"", "A refusal: \"3 critical and 3 major comments still need resolving. Verify, close out or withdraw them first.\"", "A refusal: \"1 critical and 2 major comments still need resolving. Respond to each of them and ask the reviewer again first.\"", "The close is allowed, because IK-01 is already in \"Verification\"."]'::jsonb, 0, 'The sentence counts the blockers by severity: C-01 is the one "Critical", C-03 and C-04 the two "Major". The log holds 3 "Critical" and 3 "Major" in all, but only unresolved ones are counted, and the way forward names the three moves that resolve a comment.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 4, 'One move later C-01 has been withdrawn. The coordinator asks again to close IK-01. What does the engine answer?', '["Allowed, because no \"Critical\" comment is left unresolved on the log.", "Still refused, with C-01, C-03 and C-04 blocking, because a withdrawal needs the coordinator''s close.", "Still refused, with C-03 and C-04 blocking, 2 in all, both \"Major\" and unresolved.", "Allowed, since C-03 already carries a response from the author."]'::jsonb, 2, 'Withdrawing C-01 resolves it. C-03 is "Responded" and C-04 is "Rejected", both unresolved "Major" comments, and a "Major" blocks as surely as a "Critical". A response is a claim the reviewer has not yet accepted.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 5, 'IK-01''s blocking comments are withdrawn. C-06 ("Minor"), C-07 ("Editorial") and C-09 (no severity) are still "Open". May the review close?', '["Yes: the close is allowed with those three still open.", "No: 3 open comments remain, and a review waits for every open comment before it closes.", "No: C-09 carries no severity, so the engine reads it as \"Critical\" and it blocks the close.", "No: the close waits until the coordinator has closed out C-02 and C-08 first."]'::jsonb, 0, 'Only "Critical" and "Major" block. The digest records the close as ALLOWED with a Minor, an Editorial and an unrated comment still Open. Verified comments waiting on the coordinator hold nothing open either, because they are resolved.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 6, 'summarise is run over IK-01 and its own log. What are totalComments, openComments and blockingComments?', '["9, 4 and 3, since only comments whose status reads \"Open\" are counted as open.", "8, 6 and 3, since the unrated C-09 is left out of every count.", "9, 6 and 5, since every \"Critical\" and \"Major\" comment counts as blocking.", "9, 6 and 3: every comment, every unresolved comment, and the unresolved ones rated \"Critical\" or \"Major\"."]'::jsonb, 3, 'Open counts every unresolved status: four "Open", one "Responded" and one "Rejected" make 6. Blocking is the unresolved comments rated "Critical" or "Major", which is 3. The total is every comment on the log, C-09 included.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 7, 'Where does the summary put C-09, the IK-01 comment that carries no severity?', '["In the \"Editorial\" column, the lowest severity, as well as in totalComments and openComments.", "In totalComments and openComments, and in no severity column, since it has no severity to be counted under.", "In blockingComments, because a comment with no severity is treated as \"Critical\".", "Nowhere, since an unrated comment is left out of the summary."]'::jsonb, 1, 'C-09 is a real comment, so it is in the total, and it is "Open", so it is in the open count. It has no severity to be counted under, which is why the severity columns read "Critical" 3, "Major" 3, "Minor" 1 and "Editorial" 1 and sum to 8.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 8, 'bySeverityThenAge sorts IK-01''s log for the coordinator. Which order does it return?', '["C-09, C-01, C-03, C-04, C-06, C-07, C-08, C-02, C-05.", "C-01, C-02, C-08, C-03, C-04, C-05, C-06, C-07, C-09.", "C-01, C-03, C-04, C-06, C-07, C-09, C-08, C-02, C-05.", "C-01, C-03, C-04, C-09, C-06, C-07, C-08, C-02, C-05."]'::jsonb, 2, 'Unresolved comments come first, worst severity first within them, then the resolved ones. The three blockers lead. On this log the unrated C-09 comes after every rated unresolved comment, the "Editorial" C-07 included, and before C-08, the first of the resolved comments.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 9, 'IK-02 is "In Review" with a due date of 2026-10-01. What does isOverdue answer on 2026-10-01?', '["Overdue, because its due date has arrived on the as-of date.", "Overdue, because C-12, an open \"Major\" comment, sits on it.", "Not overdue, because \"In Review\" is not one of the active stages.", "Not overdue: a review due on the as-of date is on time."]'::jsonb, 3, 'A due date is the last day the work is on time, so a review is overdue only once the date has passed. IK-01, due 2026-09-29, has passed it and reads overdue. "In Review" is an active stage, and comments play no part in the overdue rule.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 10, 'On 2026-10-01 a coordinator checks IK-04, a review in the "Cancelled" stage whose due date of 2026-08-01 passed long before. Is it overdue?', '["Overdue, because 2026-08-01 is before the as-of date and the stage plays no part.", "Not overdue, whatever its date: isOverdue asks the stage first, and \"Cancelled\" never reads overdue.", "Overdue, until the comments C-10 and C-11 on it are withdrawn.", "Not overdue, but only because its due date is more than 30 days past."]'::jsonb, 1, 'isOverdue asks the stage first. At the same past due date, 2026-09-30, "Draft", "In Review" and "Verification" read overdue, and "Closed" and "Cancelled" do not. A cancelled review has no work left to be late with.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 11, 'The whole IKANG register, five reviews and 12 comments, is summarised on 2026-10-01. What are totalComments, open and blocking?', '["12, 7 and 4, with C-10 and C-11 in neither open nor blocking.", "12, 9 and 6, with C-10 and C-11 on IK-04 counted as open and blocking.", "10, 7 and 4, with C-10 and C-11 left out of the comment total.", "12, 8 and 5, with C-12 counted twice across two reviews."]'::jsonb, 0, 'C-10 and C-11 sit on IK-04, which is "Cancelled" and locked, so nobody can resolve them. They stay in the total and in the severity and status columns and leave the open and blocking counts. C-12 is on IK-02, which is live, so the counts are IK-01''s 6 and 3 each with C-12 added.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 12, 'u-efe, the author of IK-01, is put on the review with no role given at all. What does the engine do?', '["It allows u-efe on as an Observer, the role a blank is read as.", "It refuses with \"Choose the reviewer.\", because no role was chosen.", "It refuses in the words it uses for a Reviewer, so a blank role is no way round the rule.", "It allows it, because the rule reaches only the two named reviewer roles and a blank names neither of them."]'::jsonb, 2, 'The engine refuses the author as a Reviewer, as the Lead Reviewer and with no role given, each time with "The author of the work under review cannot review it. Choose somebody independent of the work." Only an explicit Observer is allowed, because watching judges nothing.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 13, 'u-efe, the author of IK-01, asks to withdraw C-01, an "Open" comment on that work. What comes back?', '["Allowed, because \"Withdrawn\" is a legal next status from \"Open\" for anybody signed in.", "Refused: \"An open comment can only go to Responded or Withdrawn.\", since the author must respond before anything else can happen.", "Allowed, because the author may take back any comment before responding to it.", "Refused: \"The author of the work under review cannot withdraw a comment on it. A reviewer independent of the work decides it.\""]'::jsonb, 3, 'The move is legal in the table. It is refused because of who asks: "Verified", "Rejected" and "Withdrawn" are the reviewer''s moves, and the author never takes them. An author who could withdraw a "Critical" comment could clear a blocker without answering it.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 14, 'u-efe, the author of IK-01, asks to close out C-02, a comment the reviewer has already verified. What does the engine answer?', '["Allowed: the rule leaves the coordinator''s move unrestricted.", "Refused: \"The author of the work under review cannot verify a comment on it.\"", "Refused: \"A verified comment can only go to Closed.\", since the author asked.", "Refused: \"Sign in to act on this comment.\""]'::jsonb, 0, 'Segregation of duties in peer review restricts the reviewer''s three moves. The author''s own move, "Responded", and the coordinator''s, "Closed", are not restricted by it, and closing out a verified comment is administrative once the reviewer has accepted the response.'),
  ('riskchange', 'advanced', 'module', 'm02-closing-a-review', 15, 'An external reviewer is put on IK-01 named only by display name. What does the engine do, and what does that show about the independence rule?', '["It refuses, because every reviewer has to be a signed-in user of the app.", "It allows the reviewer, since a display name alone cannot be matched to the author, and the digest holds that as a limit.", "It refuses with \"Choose the reviewer.\", because a display name alone names nobody.", "It allows the reviewer as an Observer only, so nothing on the review can be judged by them."]'::jsonb, 1, 'The digest records the external reviewer as ALLOWED and lists the limit among the held items: a reviewer named by display name only cannot be matched to the author, and a review with no author recorded cannot be checked either.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 1, 'The lessonsLearned engine asks whether a lesson has substance. What must the lesson record to have it?', '["What happened and why it happened, with the date of the event beside them.", "What happened, who wrote it up and which register it was applied to.", "What happened, why it happened and what to do about it.", "Why it happened and what to do about it."]'::jsonb, 2, 'The engine checks for all three parts. The first two without the third are a story: an account of an event that tells the next person nothing they can act on.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 2, 'ON-07 on the ONNE register is a "Draft" that records only what happened. What does the engine print in its missing column?', '["\"why it happened, what to do about it\", the two parts it lacks, so substance reads no.", "\"what to do about it\", the one part a draft may leave out.", "none, because a \"Draft\" is not yet checked for substance.", "\"what happened\", since a draft has not been submitted."]'::jsonb, 0, 'The missing column names the absent parts in the engine''s own words. ON-07 has only the first of the three, so two are missing. ON-06, a "Submitted" lesson, lacks only "what to do about it".'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 3, 'u-grace, who did not write ON-06, asks to validate it. ON-06 has no recommendation. What does the engine answer?', '["Allowed, because u-grace did not write the lesson and the author-validation rule is therefore met in full.", "Refused: \"This lesson is missing what to do about it. A lesson is what happened, why it happened and what to do about it; the first two without the third are a story.\"", "Refused: \"The author of a lesson cannot validate it, and that includes recording somebody else''s name.\"", "Refused: \"This lesson has not been validated. Somebody other than its author has to accept it before it is published to everyone.\" as the lesson stands."]'::jsonb, 1, 'Independence is not the problem here: u-grace did not write ON-06. The lesson itself is incomplete. A lesson without its third part can be written and submitted, and the substance check bites at validation, naming the missing part so the author knows what to add.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 4, 'ON-05 is "Validated". How do the engine''s accepted and visible columns read for it?', '["Accepted yes and visible yes, because validation is the step that shows a lesson to everyone.", "Accepted no and visible no, because only \"Published\" and \"Embedded\" are accepted.", "Accepted no and visible yes, because a validated lesson is readable and still awaiting a decision.", "Accepted yes, visible no."]'::jsonb, 3, 'Accepted by the organisation is "Validated", "Published" and "Embedded". Visible to everyone is "Published" and "Embedded" only. Accepted and visible are different questions, and ON-05 sits between them.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 5, 'Which lesson statuses does the engine count as visible to everyone?', '["\"Validated\", \"Published\" and \"Embedded\".", "\"Published\" only, until the lesson has been embedded.", "\"Published\" and \"Embedded\".", "Every live status."]'::jsonb, 2, '"Validated", "Published" and "Embedded" is the accepted group. The visible group is narrower, and visibility decides which lessons carry a review status and which are counted in lessonsApplied and lessonsUnapplied.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 6, 'ON-08 is "Archived" and ON-09 is "Superseded". Both have substance. How does the engine read them for acceptance and visibility?', '["Accepted, since each was validated before it left use, and not visible.", "Neither accepted nor visible, because an archived or superseded lesson is out of use.", "Accepted and visible, since a lesson with substance stays on the register for everyone.", "Visible, because the archive is open to everyone, and not accepted."]'::jsonb, 1, 'The accepted group is "Validated", "Published" and "Embedded", and the visible group is "Published" and "Embedded". Neither "Archived" nor "Superseded" is in either group, and neither is live.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 7, 'ON-01 was written by u-musa. Read as if it were still "Submitted", u-musa asks to validate it. What does the engine return?', '["Refused: \"The author of a lesson cannot validate it, and that includes recording somebody else''s name. Ask a colleague who was not involved in writing it to validate it.\"", "Allowed, because the author knows the event best and the validation is recorded under the author''s name.", "Refused: \"The author of the work under review cannot review it. Choose somebody independent of the work.\"", "Refused: \"This lesson is missing what to do about it.\""]'::jsonb, 0, 'The refusal states the rule, closes the workaround of recording somebody else''s name in the same breath, and names the way forward. The sentence about the author of the work under review belongs to peer review, the same idea held in another register.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 8, 'u-musa, the author of ON-01, asks to validate it while typing a colleague''s name into the validator field. What happens?', '["It is allowed, and the colleague''s typed name is recorded as the validator of the lesson.", "It is allowed, and the typed name is filed as an external reviewer beside u-musa as actor.", "It is refused with \"Choose somebody independent of the work.\", the sentence the author of the work gets.", "It is refused in the same words the author gets without a typed name."]'::jsonb, 3, 'The actor is always the signed-in person doing the validation, whatever name is typed. The engine finds the author signed in and refuses with the sentence that already says "that includes recording somebody else''s name".'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 9, 'Under the owner decision on validation by typed name, who does the engine read as the actor of a validation?', '["The name typed into the validator field, whoever is signed in at the time.", "Whichever of the two names appears later in the lesson''s record.", "The signed-in person, whatever name is typed.", "The lesson''s author, with the typed name read as a witness to it."]'::jsonb, 2, 'This is AS15 Q10, decided on 2026-09-18. A name in a text field proves nothing about who typed it, so the engine reads the signed-in identity, and a typed name records an external reviewer and cannot launder the author.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 10, 'u-grace, signed in and not the author of ON-01, records an external reviewer by name while validating it. What does the engine do?', '["It refuses, because a typed name is only accepted when the author records it.", "It allows it: u-grace is the actor, and the typed name records who else looked at the lesson.", "It refuses, because an external reviewer has to be signed in to the app to be recorded.", "It allows it and records the external reviewer as the actor, with u-grace as a witness beside the name."]'::jsonb, 1, 'The digest records u-grace recording an external reviewer by name as ALLOWED. The actor is independent of the lesson, and the typed name adds who else looked at it, which is the legitimate use of the field.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 11, 'ON-05''s validation record is removed and it is then asked to move to "Published". What does the engine return?', '["Refused: \"This lesson has not been validated. Somebody other than its author has to accept it before it is published to everyone.\"", "Allowed, because the status reads \"Validated\" and \"Published\" is a legal next status from it.", "Refused: \"A lesson that is draft can only move to Submitted, Archived.\"", "Refused: \"Record where this lesson was applied first.\""]'::jsonb, 0, 'The status alone does not satisfy the engine. It asks for the validation record, which ties publication to an act by a person, so a lesson cannot reach everyone on the strength of a status somebody typed.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 12, 'Once an author submits a lesson, where can the lesson go from "Submitted"?', '["\"Validated\" or \"Published\", once somebody other than the author accepts it.", "\"Validated\" only, because a submitted lesson has already left its author.", "\"Published\", \"Draft\" or \"Archived\", with validation recorded along the way.", "\"Validated\", \"Draft\" or \"Archived\"."]'::jsonb, 3, 'The author writes and submits, somebody else validates, and only then can it be published. A submitted lesson can also go back to "Draft" if a gap is found, or be archived.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 13, 'Publishing a lesson checks for a validation record. Which limit does the digest list among the held items for that step?', '["Publishing does not check that a validation record exists at all.", "Publishing does not check a second time who validated the lesson.", "Publishing does not check whether the lesson has substance.", "Publishing checks the validator again and refuses the author."]'::jsonb, 1, 'The independence check sits where the validation is recorded. Publishing relies on it having been enforced there, and the digest lists that as a stated limit of the engine.'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 14, 'Read ON-01 as if it were still "Submitted". Its author, u-musa, is refused at validation. What does the owner decision on validation by typed name require before ON-01 can be validated?', '["u-musa types in the name of a colleague who was not involved in writing it and then validates it.", "u-musa validates it once the name of an external reviewer has been recorded alongside it.", "A colleague who was not involved in writing it validates it, signed in as themselves.", "It is published first, and then any member may validate it."]'::jsonb, 2, 'The refusal says "Ask a colleague who was not involved in writing it to validate it.", and under AS15 Q10 the actor is always the signed-in person doing the validation, whatever name is typed. A typed name records an external reviewer and cannot launder the author, so u-musa is refused with or without one. A lesson whose validation record is missing is refused at "Published".'),
  ('riskchange', 'advanced', 'module', 'm03-a-lesson-and-its-validation', 15, 'Why does the engine ask for a validation record at the moment of publishing, instead of trusting a status that reads "Validated"?', '["A status is one field anything can write; the record ties publication to an act by a person.", "Because the status of a validated lesson is cleared when the lesson is published.", "Because the record carries the lesson''s review date, which publishing sets for the first time.", "Because a validated lesson is already visible to everyone and needs no second check."]'::jsonb, 0, 'A validation record says who accepted the lesson and when. By asking for it, the engine stops a lesson reaching everyone on the strength of a status somebody typed, and the refusal says somebody other than its author has to accept it first.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 1, 'An application of a lesson carries one of three outcomes. Which outcomes does the engine count as having changed something?', '["\"Adopted\" only, since an adaptation changes the lesson itself.", "\"Adopted\", \"Adapted\" and \"Rejected\".", "\"Adapted\" only.", "\"Adopted\" and \"Adapted\"."]'::jsonb, 3, 'Both "Adopted" and "Adapted" count as applied and both can earn "Embedded". A rejection is a real record of a decision, and it embeds nothing because nothing changed.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 2, 'Of the eight application targets, which two are Suite registers that carry a real key?', '["\"Procedure\" and \"Training\", the two targets that name a document or a course somebody can open and read.", "\"Risk register\" and \"Management of change\", whose rows another engine in this course decides about.", "\"Risk register\" and \"Design standard\".", "\"Management of change\" and \"Maintenance plan\"."]'::jsonb, 1, 'An application into either Suite register names a risk row or a change record, each with its own state. The other six targets, "Procedure", "Training", "Design standard", "Contract or tender", "Maintenance plan" and "Other", name things outside the Suite registers.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 3, 'What does the engine hold as the difference between an "Adopted" and an "Adapted" application?', '["No rule beyond counting each separately in the reuse record; the difference is the organisation''s own reading of the words.", "An \"Adapted\" application counts as applied and cannot earn \"Embedded\".", "An \"Adopted\" application must name its target, and an \"Adapted\" one may leave it out.", "An \"Adapted\" application counts half toward the applied total."]'::jsonb, 0, 'Both count as applied, both can earn "Embedded", and the reuse record keeps them in separate columns. The engine holds no rule that tells them apart, so taking a lesson as written and changing it to fit differ only in how the organisation reads them.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 4, 'ON-01''s application log holds AA-01 ("Adopted"), AA-02 ("Adapted") and AA-03 ("Rejected"). What does its reuse record read for total, applied, adopted, adapted and rejected?', '["3, 3, 1, 1 and 1, since every application counts as applied.", "2, 2, 1, 1 and 0, since a rejection is left out of the record.", "3, 2, 1, 1 and 1.", "3, 1, 1, 0 and 1, since an adaptation is not an application."]'::jsonb, 2, 'Total is every application, applied is adopted plus adapted, and rejected is the rest: 1 adopted and 1 adapted make 2 applied, and AA-03 is the 1 rejected. The record is arithmetic on the log.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 5, 'What is ON-01''s last applied date in its reuse record?', '["2026-08-01, the date of AA-03, its latest application of any outcome on the log.", "2026-05-02, the date of AA-01, since only an adoption sets the last applied date.", "2026-07-14, the date of AA-02, its \"Adapted\" application into a procedure.", "null, because its latest application is a rejection."]'::jsonb, 2, 'A rejection applied nothing, so AA-03 on 2026-08-01 is later and does not move the date. Both "Adopted" and "Adapted" are applications that changed something, and AA-02 is the later of the two.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 6, 'ON-03 has one application, AA-05, a rejection dated 2026-07-01. What is its last applied date?', '["2026-07-01, the date of its one application.", "2026-06-05, the event date of the lesson itself.", "2026-10-31, the review date it carries.", "null."]'::jsonb, 3, 'There is no date on which ON-03 was applied to anything, because its only application is a rejection. ON-04 also reads null, with no application at all behind it.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 7, 'ON-03, whose one application is a rejection, is asked to move to "Embedded". What does the engine return?', '["Allowed, because the lesson has an application on its log and is \"Published\".", "Refused: \"This lesson has been considered 1 time and adopted nowhere. Record where it was applied before calling it embedded.\"", "Refused: \"Record where this lesson was applied first: the risk it raised, the change it caused, the procedure or the course it altered.\"", "Refused: \"Say why it was not adopted.\""]'::jsonb, 1, 'The engine counts the consideration, which is honest, and still refuses the status, which is correct. The sentence that lists the risk, the change, the procedure or the course belongs to ON-04, which has no application at all.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 8, 'ON-04 is "Published" and has no application at all. Asked to mark it "Embedded", how does the engine''s refusal end?', '["\"A lesson that changed nothing has not been learned.\"", "\"Record where it was applied before calling it embedded.\"", "\"Somebody other than its author has to accept it before it is published to everyone.\"", "\"Name the lesson that replaces this one.\""]'::jsonb, 0, 'The full refusal reads: "Record where this lesson was applied first: the risk it raised, the change it caused, the procedure or the course it altered. A lesson that changed nothing has not been learned." The sentence about calling it embedded is ON-03''s.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 9, 'ON-10 is "Published". Somebody asks to archive it and gives no reason. What comes back?', '["Allowed, because archiving is open from every live status.", "Refused: \"Say why this lesson is being archived. \"Archived, nobody said why\" is how a lessons database becomes a folder of PDFs.\"", "Refused: \"An archived lesson is final.\"", "Refused: \"Name the lesson that replaces this one.\", since archiving needs a successor as superseding does."]'::jsonb, 1, 'Archiving is open from every live status, and the engine still asks why. A lesson that disappears without a reason leaves the next reader unable to tell whether it was wrong, out of date or tidied away. With a reason, the archive of ON-10 is allowed.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 10, 'ON-10 is asked to be superseded, naming ON-10 itself as the successor. What does the engine return?', '["\"Name the lesson that replaces this one.\", since a lesson naming itself names no successor.", "Allowed, because a successor has been named and the engine checks for one.", "\"A lesson that is published can only move to Embedded, Archived.\"", "\"A lesson cannot supersede itself.\", the refusal for a successor that makes no sense."]'::jsonb, 3, 'The engine refuses the move with no successor named, and refuses the one successor that makes no sense in its own words. Superseding is open from "Published", so the move itself is legal for ON-10.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 11, 'From which lesson statuses may a lesson be superseded?', '["\"Published\" and \"Embedded\", the two visible statuses.", "Every live status, as archiving is, since both are exits from use.", "\"Embedded\" only, once the lesson has proved it changed something.", "\"Validated\" and \"Published\"."]'::jsonb, 0, 'The legal table gives "Superseded" from "Published" and from "Embedded" only, and archiving from every live status. Neither exit has a way back: "Archived" and "Superseded" list no next status.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 12, 'A rejection is recorded against the risk register with its reason and no risk named. What does the engine return?', '["Allowed, because a rejection changes nothing, so the target it names does not matter.", "Refused: \"Say why it was not adopted.\", since the reason is checked before the target.", "Refused: \"Name the risk. A lesson pushed into the register points at the row it raised or changed, so the trail runs both ways.\"", "Allowed, because the reason alone is what a rejection has to carry, and this one carries it in full."]'::jsonb, 2, 'The target checks come before the outcome check, so a rejection carries the same trail as an adoption, plus its reason. The reason here is given, and the missing risk is what is refused.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 13, 'Somebody logs that a lesson was turned down for a procedure, names the procedure, and writes nothing about why. What does the engine say?', '["\"Say why it was not adopted. A rejection is a decision, and the next person to read this lesson needs the reasoning.\"", "\"Was the lesson adopted, adapted, or rejected?\", because a rejection with no reason is an outcome the register does not know.", "\"Pick what this lesson was applied to.\", since a rejection has no target in the engine''s reading of it.", "Nothing: a rejection changes nothing, so the engine records it as it stands with no reason attached to it."]'::jsonb, 0, 'A rejection must carry its reason. With the reason, the digest records the rejection as ALLOWED. The question about adopted, adapted or rejected is the refusal for an outcome the register does not know.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 14, 'The ONNE summary counts applications 6, applied 4 and rejected 2. Which applications make up the 4?', '["AA-01, AA-02, AA-03 and AA-04, the first four on the log.", "AA-01, AA-02, AA-04 and AA-06.", "AA-02, AA-03, AA-05 and AA-06, the ones applied after 2026-06-10.", "AA-01, AA-04, AA-05 and AA-06, the ones on single-application lessons."]'::jsonb, 1, 'applied counts the "Adopted" and "Adapted" applications. AA-03 and AA-05 are the two rejections. intoRiskRegister 1 and intoMoc 1 are AA-01 and AA-04, the two applications into the Suite registers.'),
  ('riskchange', 'advanced', 'module', 'm04-proof-of-use', 15, 'ON-01''s reuse record lists the targets it changed. Which are they?', '["\"Risk register\", \"Procedure\" and \"Training\".", "\"Risk register\" only.", "\"Procedure\" and \"Training\".", "\"Risk register\" and \"Procedure\"; its \"Training\" application was a rejection."]'::jsonb, 3, 'The targets changed column lists only the targets of applications that changed something. AA-03 into "Training" was "Rejected", so training is absent. ON-03, whose only application was rejected, reads none.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 1, 'A visible lesson''s review is due 2026-10-31. How does it read on 2026-10-01?', '["Neither, being one day outside the lead.", "\"review overdue\", because a lesson inside its lead is already late for review.", "\"review due soon\", being 30 days away, and not overdue.", "\"review due soon\" and \"review overdue\" together, since the lead has been entered."]'::jsonb, 2, 'REVIEW_LEAD_DAYS is 30, with both ends counted, so a review 30 days away is still due soon. At 31 days away, a review due 2026-11-01, the lesson reads neither. No row of the edge table reads both.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 2, 'On 2026-10-01, the as-of date, a published lesson reaches its review date that very day. Which review status does the engine give it?', '["Due soon and not overdue: 0 days away, the date has arrived and has not passed.", "Overdue and not due soon, because the review date has been reached.", "Neither, because a review due today is outside the lead.", "Overdue and due soon together."]'::jsonb, 0, 'A lesson reads review overdue only once its date has passed, which is the row at -1 days, a review due 2026-09-30. At 0 days the lesson is inside the lead, so it reads due soon.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 3, 'ON-05 has been validated and is not yet published, and its review falls on 2026-10-06. Which review status does the engine give it on 2026-10-01?', '["\"review due soon\", being inside the 30-day lead before its date.", "\"review overdue\", because a validated lesson has to be reviewed before it can be published.", "\"review due soon\", counted in reviewsDueSoon on the summary.", "None at all."]'::jsonb, 3, 'Only a visible lesson, "Published" or "Embedded", has a review status. ON-05 is accepted and not yet visible to anybody, so it reads neither overdue nor due soon, and reviewsDueSoon 2 is ON-01 and ON-03.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 4, 'On 2026-10-01 the ONNE summary reads reviewsOverdue 1. Which lesson is it, and why?', '["ON-08, \"Archived\", at 607 days the oldest lesson on the register.", "ON-02, \"Embedded\", whose review date of 2026-09-20 has passed.", "ON-05, \"Validated\", whose review date is only days away.", "ON-04, \"Published\", which has no review date at all."]'::jsonb, 1, 'Age carries no status of its own. ON-02 is visible and its review date has passed, so it is the one overdue review. ON-08 is not visible and has no review status, and ON-04 with no review date reads neither.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 5, 'The ONNE summary reads lessonsApplied 3 and applied 4. What does each count?', '["Both count applications, lessonsApplied over visible lessons only and applied over every lesson.", "lessonsApplied counts visible lessons; applied counts applications.", "Both count lessons, and applied also includes the lessons that were rejected somewhere.", "lessonsApplied counts applications and applied counts lessons."]'::jsonb, 1, 'lessonsApplied 3 is ON-01, ON-02 and ON-10, the visible lessons with at least one adoption or adaptation. applied 4 counts the adopting and adapting applications themselves, two of which belong to ON-01.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 6, 'lessonByAttention orders the ONNE register on 2026-10-01. Why does ON-03 come before ON-04?', '["ON-03 has a review date inside the lead and ON-04 has none.", "ON-03 has an application on its log and ON-04 has none.", "ON-03 is older, and older lessons come first within a rank.", "Both are visible lessons nobody has applied, and ON-03''s event date, 2026-06-05, is newer than 2026-05-30."]'::jsonb, 3, 'The ranks run: visible lessons nobody has applied, then lessons awaiting validation, then overdue reviews, then other live lessons, then the rest, newest event first within a rank. ON-03 and ON-04 share the first rank, so their event dates decide.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 7, 'A lesson''s age is counted to the as-of date. From which date is it counted?', '["From its event date.", "From the date it was validated, when the organisation accepted it.", "From its last applied date, since that is the last time it was used.", "From the local date of its creation timestamp, whatever else it records."]'::jsonb, 0, 'Age counts from the event date. Only a lesson with no event date falls back to its creation timestamp, read as the local calendar date, so the same row can be a day older in Lagos than in UTC. Every ONNE lesson records its event date.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 8, 'The application counts in the lessons summary carry a stated limit. Which one does the digest list among the held items?', '["They leave out rejections.", "They count only the visible lessons'' applications, like lessonsApplied does.", "They include applications on lessons that are not visible.", "They count each lesson once, however many applications it has on its log."]'::jsonb, 2, 'The lesson counts beside them, lessonsApplied and lessonsUnapplied, cover visible lessons only. The application counts do not narrow the same way, and the digest lists that as a held item taught as a limit and graded nowhere.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 9, 'A peer review summary is handed a comment whose review is missing from the list of reviews. What does the digest hold it does?', '["It drops the comment from every count, because nothing can be read without its review.", "It refuses the whole summary until the missing review is added to the list it was handed.", "It counts the comment in the total only.", "It still counts the comment as open work, as an MOC action with an unknown change does."]'::jsonb, 3, 'The summary keeps a finished review''s comments out of the open and blocking counts only when it can see the review. A comment it cannot place is counted as open work, and the digest lists that as a held item.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 10, 'Which of these is an owner decision taken on 2026-09-18 under AS15?', '["A band found by its lower edge alone, so any positive score bands.", "Q3, fractional levels unscored.", "countByBand counting whatever population it is handed by the caller.", "Publishing checking only that a validation record exists."]'::jsonb, 1, 'The owner decisions are D1, Q9, Q10 and Q3. The other three options are held items: limits no owner has decided, taught as limits. An engine that disagrees with an owner decision is wrong; a held item is a stated boundary.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 11, 'What does owner decision D1 cover in these engines?', '["Segregation of duties on change approvals and, from ASC-0, on peer review.", "Segregation of duties on lesson validation by a typed name.", "The emergency change authority and the ratification window.", "Fractional levels, left unscored on the matrix."]'::jsonb, 0, 'Q10 is validation by typed name, Q9 is emergency change authority and the ratification window, and Q3 is fractional levels unscored. All four were taken on 2026-09-18 under AS15.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 12, 'The digest measures peerReview_cases.json by reading it. What does it record for cases, cases carrying a repaired marker, and functions exercised?', '["345, 19 and 26.", "184, 17 and 38.", "184, 38 and 17.", "291, 69 and 15."]'::jsonb, 2, '345, 19 and 26 are lessonsLearned_cases.json, and 291, 69 and 15 are managementOfChange_cases.json. Golden cases total 1037 across the five files, and the gate replays every case in five time zones.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 13, 'A golden case and the oracle bridge both check the engine. On which records does each check it?', '["Both on this course''s records, the golden case in five zones and the bridge in one zone.", "A golden case on this course''s records; the bridge on the records the oracle author chose.", "A golden case on the records the oracle author chose; the bridge on this course''s records.", "Both on the oracle author''s records, replayed from the golden files."]'::jsonb, 2, 'The bridge, oracle_bridge.py, replays every engine answer in the digest, IKANG and ONNE included. A defect that shows on only one record slips past a check that never meets it, which is why both exist.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 14, 'A change has finished, and one of its actions still reads "Open". What do openActions and overdueActions do with that action today?', '["They count it as open work until the action itself reads \"Complete\" or \"Cancelled\".", "They skip it only on a change in the Closed stage, and count it on a Cancelled one.", "They skip it, as they skip an action whose change is not in the register.", "They skip it: a finished change is locked, so its actions are not open work."]'::jsonb, 3, 'On 2026-10-01 the summary skips AC-06 and AC-07, whose changes, ES-06 in the Closed stage and ES-09 "Cancelled", are finished and locked, and a probe on the "Rejected" ES-11 counts its open action nowhere. AC-09, whose change is not in the register, still counts, and the digest holds that as a limit.'),
  ('riskchange', 'advanced', 'module', 'm05-what-the-engines-do-not-know', 15, 'Today, how does the peer review summary count an unresolved "Critical" comment that sits on a "Cancelled" review?', '["In the comment total and its severity and status columns, and in neither the open nor the blocking count.", "In the open and blocking counts for as long as it stays unresolved, whatever its review''s stage.", "Nowhere at all, the comment total included, because its review is locked.", "In the open count and not the blocking count, because nobody can resolve it."]'::jsonb, 0, 'A "Cancelled" review is locked, and nobody can move a comment on it, so a work count that included one could never fall. The summary lists such a comment in every column that describes the log and leaves it out of the counts of work still owed. The digest''s case is C-10 on IK-04.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 1, 'ON-01 was applied into the risk register on 2026-05-02, naming OB-07, Pump house flooded in the rainy season. How does OB-07 read at the other end of that trail?', '["\"Closed\", residual 8, \"Medium\", \"Within appetite\", since the lesson has been applied to it.", "\"Realized\", residual 8, \"Medium\", \"Within appetite\".", "\"Realized\", residual 8, \"High\", \"Above appetite\", because the risk has already happened.", "\"Realized\", residual 12, \"High\", \"Within appetite\"."]'::jsonb, 1, 'OB-07 is a record with its own state, decided by the riskScoring engine from its own fields. The lesson that names it points at that row, and the risk''s status, residual, band and appetite answer stay the risk''s own.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 2, 'ON-02 was applied into the change register on 2026-06-10. Which change does it name, and what stage is that change in?', '["ES-06, Revised operating procedure for glycol regeneration, now in \"Implementation\".", "OB-07, Pump house flooded in the rainy season, now \"Realized\".", "ES-06, with its stage set to \"Embedded\" by the lesson that names it.", "ES-06, Revised operating procedure for glycol regeneration, now \"Closed\"."]'::jsonb, 3, '"Closed" here is a stage of a change, decided by the managementOfChange engine from the change''s own approvals and actions. "Embedded" is a lesson status, ON-02''s own, and OB-07 is the risk ON-01 names.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 3, 'AA-01 records ON-01 going into the risk register. What must that application carry for the engine to record it?', '["The risk it points at, OB-07, so the trail can be walked from the lesson to the row and back.", "Only its outcome, since a risk register target is a Suite register the engine already knows.", "The residual score of the risk at the time the lesson was applied.", "A reference to a procedure, as every application outside the Suite needs."]'::jsonb, 0, 'The digest records an application into the risk register that names the risk as ALLOWED, and refuses one that names no risk. Both ends carry a key: the lesson names the row, and the row is a record with its own state.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 4, 'The ONNE summary reads intoRiskRegister 1 and intoMoc 1. Which applications are they?', '["AA-01 and AA-02, the two applications of ON-01 that changed something.", "AA-04 and AA-06, the two adoptions dated after 2026-06-01, whatever their targets.", "AA-01 and AA-04, the two applications into Suite registers.", "AA-03 and AA-05."]'::jsonb, 2, 'AA-01 is ON-01 into the "Risk register", naming OB-07. AA-04 is ON-02 into "Management of change", naming ES-06. AA-02 went into a procedure and AA-06 into a maintenance plan, neither of them a Suite register.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 5, 'ON-06 records its source type as "Audit finding". How far does this course go with that audit and its finding?', '["It scores the finding on the five by five matrix before the lesson that cites it is validated.", "It follows the finding through its own lifecycle until the finding closes.", "It reads them only as the source of the lesson; they belong to Compliance, Audit & Quality.", "It checks that the audit was independent before accepting the lesson."]'::jsonb, 2, 'Compliance, Audit & Quality owns audit independence, the audit and finding lifecycles and root-cause categories. This course names an audit finding as the source of a lesson and stops there.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 6, 'Working the chain on IK-01, a reader asks two questions of each comment to find its blockers. One is its severity. What is the other?', '["Whether each comment''s status is resolved.", "Whether the review is overdue on 2026-10-01, since a late review cannot close.", "Who wrote each comment, since that decides blocking.", "How many comments the log holds in total, since blocking is a share of the total."]'::jsonb, 0, 'Resolved first, then blocking: the resolved statuses are "Verified", "Closed" and "Withdrawn", which leaves 6 unresolved on IK-01. Asking those six for "Critical" or "Major" leaves 3 blocking.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 7, 'In the chain, a reader is tempted to skip C-03 and C-04 on IK-01 because a response exists on one and a rejection is recorded on the other. Why must they stay in the blocking count?', '["They stay only until the coordinator records the review as overdue.", "A response or a rejection turns a \"Major\" comment into a \"Critical\" one.", "They must stay because every comment on a review in \"Verification\" blocks until it closes.", "\"Responded\" and \"Rejected\" are both unresolved, and both comments are \"Major\"."]'::jsonb, 3, 'Only the reviewer''s verification turns a response into a resolved comment, and a rejection means the reviewer did not accept the response. Both statuses therefore still wait on somebody, and a "Major" comment that is unresolved blocks.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 8, 'IK-01 is in "Verification" and was due 2026-09-29. What does the chain record for its overdue reading?', '["Overdue, with no date needed, because 2026-09-29 is in the past on every day this course is read.", "Overdue on 2026-10-01, with that date written beside the verdict.", "Not overdue, as \"Verification\" is finished.", "Not overdue, its blockers hold the clock."]'::jsonb, 1, '"Verification" is an active stage, and 2026-09-29 has passed on 2026-10-01. A status without its as-of date cannot be checked, because every date rule answers a different question on a different day.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 9, 'ON-01''s review is due 2026-10-20. What review status does the chain record for it on 2026-10-01?', '["It is inside the lead, so the engine reads review due soon.", "\"review overdue\", because ON-01 has passed 203 days of age since its event.", "Neither, because a lesson that is embedded has no review status.", "Neither, since 2026-10-20 sits outside the 30-day lead."]'::jsonb, 0, 'ON-01 is visible and 2026-10-20 falls inside the 30-day lead on 2026-10-01, so it reads review due soon. Age carries no status of its own. Had ON-01 been "Validated" like ON-05, it would carry no review status at all.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 10, 'With 2 applied on its reuse record, what does the chain record for marking ON-01 "Embedded"?', '["Refused, because its rejected application must be withdrawn first.", "Refused: \"This lesson has been considered 1 time and adopted nowhere.\"", "Refused, until the review due on 2026-10-20 is done.", "Allowed."]'::jsonb, 3, 'An adoption into the "Risk register" and an adaptation into a "Procedure" are evidence of use, so the move is allowed. The considered-and-adopted-nowhere refusal is ON-03''s, whose one application is a rejection.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 11, 'ON-02 is "Embedded". Which record is the evidence of use that its status rests on?', '["Its validation record, which is all Embedded asks beyond Published.", "AA-01, the adoption that named OB-07 in the risk register.", "AA-04, its \"Adopted\" application into the change register, naming ES-06.", "Its review date, 2026-09-20, which keeps it current."]'::jsonb, 2, 'Embedded is earned by an application that changed something: ON-04, with none, and ON-03, with only a rejection, are both refused it. ON-02''s reuse record holds one application, AA-04, applied 1 into "Management of change". AA-01 is ON-01''s, and a review date says nothing about use.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Segregation of duties in peer review, the author never reviewing the work, is held where today?', '["In the app and the database already, with the engine following later.", "In the engine; the app and the database follow with the Suite pull request that ships ASC-0.", "In the database only, as a constraint on who can be put on a review.", "Nowhere yet: it is listed among the held items as a limit."]'::jsonb, 1, 'The engine enforces the rule now, from ASC-0, as owner decision D1 applied to peer review. A lesson that told a learner the app already refuses the author would be teaching something the digest does not say.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 13, 'Which of these does the peerReview engine hand to a person rather than decide itself?', '["Whether the author''s response is good enough to accept.", "Whether a \"Major\" comment that is \"Rejected\" still blocks the review from closing.", "Whether the author may verify.", "Whether a comment with no response text may be verified by the reviewer."]'::jsonb, 0, 'The engine checks that the right people acted and that the record is complete. It decides blocking, refuses the author a reviewer''s move and refuses a verification with no response text. Whether a response deserves to be accepted it leaves to a person, in its own words: "A reviewer independent of the work decides it."'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 14, 'The Lessons Learned dashboard and the ONNE register on 2026-10-01: what does the digest record about reviewsOverdue and reviewsDueSoon?', '["The dashboard displays them, and the engine leaves both uncomputed on this register.", "They read 1 and 2; the dashboard computes both and shows neither.", "The engine computes them as 2 and 1, and the dashboard shows only the first of the two.", "Neither is computed, because the dashboard reads lessons one at a time."]'::jsonb, 1, 'The engine''s summary reads reviewsOverdue 1 and reviewsDueSoon 2 on the ONNE register. The digest records beside them that the dashboard computes both and displays neither: the engine answers, and whether a user sees the answer is the app''s part.'),
  ('riskchange', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Across the three tiers of this course, the same kind of rule keeps the person with most interest in a yes from giving it. Which set of three refusals shows that rule?', '["The author responding to a comment, the coordinator closing it out, the reviewer withdrawing it.", "A band read from its lower edge, a residual that falls back, a target that declines.", "An archive with no reason, a supersede with no successor, a draft sent straight to publication.", "The originator approving a change, the author reviewing their own work, the author validating their own lesson."]'::jsonb, 3, 'Segregation of duties runs through every register: the originator of a change never approves it, the author of work under review never reviews it, and the author of a lesson never validates it. The author''s own response and the coordinator''s close are allowed.'),
  ('riskchange', 'advanced', 'final', null, 1, 'A comment is raised and later closed by the shortest legal path. Which statuses does it pass through after "Open", and who makes each move?', '["\"Responded\" by the author, \"Verified\" by the reviewer, then \"Closed\" by the coordinator.", "\"Verified\" by the reviewer, then \"Closed\" by the coordinator, with no response from the author needed.", "\"Responded\" by the author, then \"Closed\" by the reviewer.", "\"Responded\" by the author, \"Verified\" by the coordinator, then \"Closed\" by the reviewer."]'::jsonb, 0, 'Each role owns its step. The author answers, the reviewer accepts the answer, and the coordinator records the comment as finished. The other exit, withdrawal, finishes a comment without ever reaching "Closed".'),
  ('riskchange', 'advanced', 'final', null, 2, 'A reviewer tries to withdraw a comment that the author has already responded to. What does the engine say?', '["\"A withdrawn comment is final.\"", "\"The author of the work under review cannot withdraw a comment on it.\"", "Nothing: withdrawing is the reviewer''s own move.", "Refused: a response now stands, so the only moves are to Verified or Rejected."]'::jsonb, 3, 'The engine''s sentence is "A responded comment can only go to Verified or Rejected." Withdrawal is reachable from "Open" and from "Rejected" only, so once a response exists the reviewer judges it first, and may withdraw again only after rejecting.'),
  ('riskchange', 'advanced', 'final', null, 3, 'Of the 7 legal comment moves, how many belong to the reviewer?', '["3, one each for \"Verified\", \"Rejected\" and \"Withdrawn\".", "4: \"Withdrawn\" from two statuses, \"Verified\" and \"Rejected\" from one.", "2: \"Verified\" and \"Rejected\", both from \"Responded\".", "5, every move out of \"Open\", \"Responded\" and \"Rejected\"."]'::jsonb, 1, 'The author has "Responded" from "Open" and from "Rejected", 2 moves. The coordinator has "Closed" from "Verified", 1 move. The reviewer has the other 4, which is why the person being reviewed answers and the person reviewing decides.'),
  ('riskchange', 'advanced', 'final', null, 4, 'Nobody is signed in when a request arrives to verify C-03, a "Responded" comment on IK-01. What comes back?', '["\"Sign in to act on this comment.\"", "The move is allowed, since \"Verified\" is legal from \"Responded\".", "\"A comment cannot be verified before the author has responded to it.\"", "\"Choose the reviewer.\", since nobody acted."]'::jsonb, 0, 'With nobody signed in there is no actor to check, and the engine says so. "Choose the reviewer." is the refusal when a review is given a reviewer with nobody named at all.'),
  ('riskchange', 'advanced', 'final', null, 5, 'A reviewer clicks "Rejected" on a comment that is already "Rejected". What does the engine answer?', '["\"A rejected comment can only go to Responded or Withdrawn.\"", "The same-status sentence: \"This comment is already rejected.\"", "\"A rejected comment is final.\"", "The move is allowed and the rejection is recorded a second time on the comment."]'::jsonb, 1, 'A move to the status a comment already holds has its own family of sentences. The record does not change, and nothing pretends it did.'),
  ('riskchange', 'advanced', 'final', null, 6, 'Which comment statuses wait on the author?', '["\"Responded\" and \"Rejected\".", "\"Open\" only.", "\"Open\", \"Responded\" and \"Rejected\", the three unresolved statuses.", "\"Open\" and \"Rejected\"."]'::jsonb, 3, 'Of the three unresolved statuses, "Open" and "Rejected" wait on the author to respond, and "Responded" waits on the reviewer to verify or reject.'),
  ('riskchange', 'advanced', 'final', null, 7, 'Which review stages read overdue at a due date of 2026-09-30, asked on 2026-10-01?', '["\"In Review\" and \"Verification\" only.", "Every stage, \"Closed\" and \"Cancelled\" included.", "\"Draft\", \"In Review\" and \"Verification\".", "\"Verification\" only, as the last stage before a close."]'::jsonb, 2, 'isOverdue asks the stage first. Only a review in an active stage, "Draft", "In Review" or "Verification", reads overdue once its due date has passed.'),
  ('riskchange', 'advanced', 'final', null, 8, 'byUrgency sorts the IKANG register on 2026-10-01. Which order comes back?', '["IK-01, IK-02, IK-05, IK-04, IK-03.", "IK-01, IK-02, IK-05, IK-03, IK-04, the latest finished first.", "IK-04, IK-03, IK-01, IK-02, IK-05, oldest due date first.", "IK-02, IK-01, IK-05, IK-04, IK-03, by stage order."]'::jsonb, 0, 'Overdue reviews first, then other active reviews, then everything finished; within a rank the earlier due date first. IK-01 is the one overdue review. IK-02 is due before IK-05. IK-04, due 2026-08-01, comes before IK-03, due 2026-08-15.'),
  ('riskchange', 'advanced', 'final', null, 9, 'Why are C-10 and C-11 left out of the open and blocking counts for the IKANG register?', '["They are \"Minor\" comments, which never block whatever their status is.", "They sit on IK-04, which is \"Cancelled\" and locked, so nobody can resolve them.", "They are resolved, having been withdrawn when IK-04 was cancelled by the coordinator.", "They are left out of the comment total as well, because their review is finished."]'::jsonb, 1, 'Judged on its own, C-10 ("Critical", "Open") and C-11 ("Major", "Responded") would each block. Nobody can resolve a comment on a locked review, so the summary keeps both in the comment total and leaves them out of the open and blocking counts.'),
  ('riskchange', 'advanced', 'final', null, 10, 'What do IK-01''s severity columns read in its own summary?', '["\"Critical\" 1, \"Major\" 2, \"Minor\" 1, \"Editorial\" 1, counting unresolved comments only.", "\"Critical\" 3, \"Major\" 3, \"Minor\" 1, \"Editorial\" 2, with C-09 counted as \"Editorial\".", "\"Critical\" 4, \"Major\" 3, \"Minor\" 1, \"Editorial\" 1.", "\"Critical\" 3, \"Major\" 3, \"Minor\" 1, \"Editorial\" 1."]'::jsonb, 3, 'The severity columns count every rated comment on the log, resolved or not. C-09 carries no severity and is in no severity column, although it is in the total and in openComments.'),
  ('riskchange', 'advanced', 'final', null, 11, 'Can the person whose work IK-01 examines sit in on it purely to watch?', '["Yes, as an Observer, a role that judges nothing.", "No: \"The author of the work under review cannot review it.\" covers every role.", "No: \"Choose the reviewer.\"", "Yes, and while observing u-efe may also verify comments."]'::jsonb, 0, 'The author, u-efe, is refused as a Reviewer, as the Lead Reviewer and with no role given, and is refused every reviewer move on a comment. Watching judges nothing, so the digest records the author as an Observer as ALLOWED.'),
  ('riskchange', 'advanced', 'final', null, 12, 'The coordinator tries to add a reviewer to IK-01 without naming anybody. What is the answer?', '["The review goes ahead with no reviewer, to be named later.", "It records a blank reviewer and lets the author fill it in.", "It refuses: \"Choose the reviewer.\"", "\"The author of the work under review cannot review it.\""]'::jsonb, 2, 'Naming nobody at all is refused with its own short sentence. The independence rule has nothing to test until somebody is named.'),
  ('riskchange', 'advanced', 'final', null, 13, 'u-kemi, independent of the work, asks to verify C-03 on IK-01, a "Responded" comment with its response written. What does the engine do?', '["The verification goes through for u-kemi.", "Refuses it, because only the coordinator may verify a comment on a review in \"Verification\".", "Refuses it, because u-kemi was not the reviewer who raised C-03 on the log.", "Refuses it with \"A comment cannot be verified before the author has responded to it.\""]'::jsonb, 0, 'The move is legal from "Responded", a response exists, and the actor is independent of the work, so the digest records it as ALLOWED. The author verifying the same comment is refused.'),
  ('riskchange', 'advanced', 'final', null, 14, 'C-03 on IK-01 has been answered by the author and reads "Responded". Which of IK-01''s summary counts does it sit in?', '["totalComments only, because an answered comment is no longer open.", "totalComments and openComments, because an answered comment no longer blocks.", "blockingComments only, because a \"Major\" comment counts nowhere else.", "totalComments, openComments and blockingComments, since the reviewer has not accepted the response."]'::jsonb, 3, 'C-03 counts in totalComments 9, openComments 6 and blockingComments 3. A response is a claim the reviewer has not yet accepted, so it moves neither the open nor the blocking count until the reviewer verifies it.'),
  ('riskchange', 'advanced', 'final', null, 15, 'In bySeverityThenAge over IK-01''s log, why does C-08, a "Critical" comment, come after C-09, a comment with no severity at all?', '["C-08 is \"Closed\" and so resolved, and every unresolved comment comes before every resolved one, whatever its severity.", "C-09 is read as \"Critical\" too, and between two comments of equal severity the older one sorts first.", "The list runs by comment number within each severity, and C-09 was raised after C-08.", "A \"Closed\" comment drops to the very end of the list, behind even the \"Verified\" C-02."]'::jsonb, 0, 'The sort puts unresolved before resolved and the worst severity first within each group. The six unresolved comments lead, and C-08, C-02 and C-05 follow as the resolved ones. C-09 cannot be read as "Critical", because it comes after the "Minor" C-06 and the "Editorial" C-07.'),
  ('riskchange', 'advanced', 'final', null, 16, 'From which point in its life does the engine treat a lesson as accepted by the organisation, and which statuses does that cover?', '["From publication only, covering the two visible statuses.", "From submission, covering \"Submitted\", \"Validated\" and \"Published\".", "From the moment it is written, covering every live status.", "Every status from validation onward among the live ones: \"Validated\", \"Published\", \"Embedded\"."]'::jsonb, 3, 'Accepted starts at validation, the step where somebody other than the author accepts the lesson. Visible is narrower, and live is wider, adding "Draft" and "Submitted".'),
  ('riskchange', 'advanced', 'final', null, 17, 'Reading a "Validated" lesson, its validator finds a gap. Instead of publishing it, where can the lesson go?', '["Nowhere: once validated, a lesson can only be published or archived.", "Straight back to \"Draft\" in a single move.", "To \"Superseded\", pending a better version.", "Back to \"Submitted\", and from there to \"Draft\"."]'::jsonb, 3, 'From "Validated" the legal moves are "Published", "Submitted" and "Archived", and from "Submitted" they include "Draft". The lesson goes back to its author rather than being published with the gap in it.'),
  ('riskchange', 'advanced', 'final', null, 18, 'ON-06 is "Submitted". What do its substance and missing columns read?', '["Substance yes; missing none.", "Substance no; missing \"why it happened, what to do about it\".", "Substance no; missing \"what to do about it\".", "Substance no; missing \"what happened\"."]'::jsonb, 2, 'ON-06 records what happened and why and lacks its recommendation. ON-07, the "Draft", is the lesson missing "why it happened, what to do about it".'),
  ('riskchange', 'advanced', 'final', null, 19, 'With u-grace''s validation on record, may ON-05 now go out to everyone?', '["Yes: the move to \"Published\" goes through.", "No: a lesson must be embedded before it can be published.", "No: \"This lesson has not been validated.\"", "No: it waits until its review date of 2026-10-06 has passed."]'::jsonb, 0, 'With a validation record by somebody other than the author, the move from "Validated" to "Published" is allowed. With the record removed, the same move is refused, because the engine asks for the record and never trusts the status alone.'),
  ('riskchange', 'advanced', 'final', null, 20, 'How many lesson statuses does the engine know, and how many of those are visible to everyone?', '["Seven, and five of them are visible, being the live ones.", "Seven, and two of them are visible to everyone.", "Five, all of them live and visible.", "Seven, and three of them are visible, from validation onward."]'::jsonb, 1, 'The seven are "Draft", "Submitted", "Validated", "Published", "Embedded", "Archived" and "Superseded". Five are live, three are accepted, and only "Published" and "Embedded" are visible.'),
  ('riskchange', 'advanced', 'final', null, 21, 'Who may validate ON-01, which u-musa wrote?', '["u-musa, provided a colleague''s name is typed in the validator field.", "u-grace, who did not write it.", "Anybody signed in, since the lesson is already \"Published\".", "Only an external reviewer named by display name."]'::jsonb, 1, 'The digest records u-grace validating ON-01, read as if it were still "Submitted", as ALLOWED, and refuses u-musa with or without a typed colleague name.'),
  ('riskchange', 'advanced', 'final', null, 22, 'A lesson is "Embedded". Which moves are still open to it?', '["None: \"Embedded\" is the last status a lesson reaches.", "\"Published\", if the application behind it is withdrawn.", "\"Superseded\" only, since an embedded lesson cannot be archived.", "It can still be superseded by a successor, or archived."]'::jsonb, 3, 'From "Embedded" the legal table lists "Superseded" and "Archived". Embedded is visible and accepted, so an embedded lesson is still read and still reviewed until it is replaced or taken out of use.'),
  ('riskchange', 'advanced', 'final', null, 23, 'What does ON-02''s reuse record read?', '["Total 1, applied 0, adopted 0, last applied null, targets changed none.", "Total 1, applied 1, adapted 1, last applied 2026-06-10, targets changed \"Procedure\".", "Total 1, applied 1, adopted 1, last applied 2026-06-10, targets changed \"Management of change\".", "Total 2, applied 1, adopted 1, last applied 2026-09-20, targets changed \"Management of change\"."]'::jsonb, 2, 'ON-02 has one application, AA-04, an adoption into "Management of change" on 2026-06-10, naming ES-06. 2026-09-20 is its review date, which has nothing to do with the reuse record.'),
  ('riskchange', 'advanced', 'final', null, 24, 'A "Draft" lesson is asked to move straight to "Published". What does the engine say?', '["\"This lesson has not been validated.\"", "\"A lesson that is draft can only move to Submitted, Archived.\"", "\"A lesson that is draft is final.\"", "Nothing: the move is allowed when the lesson has substance."]'::jsonb, 1, 'The legal table gives a draft two moves, to "Submitted" and to "Archived". A draft goes on through submission and validation, or it is archived.'),
  ('riskchange', 'advanced', 'final', null, 25, 'An "Archived" lesson is asked to move to any other status. What comes back?', '["\"Say why this lesson is being archived.\"", "\"A lesson that is archived can only move to Draft.\"", "\"An archived lesson is final.\"", "Nothing: an archived lesson can be restored to \"Published\" by its author."]'::jsonb, 2, '"Archived" has no legal next status. The record of why a lesson left use stays as it was written, and the same holds for "Superseded".'),
  ('riskchange', 'advanced', 'final', null, 26, 'A published lesson is being replaced, and the form reaches the engine with the successor field empty. What does it say?', '["\"A lesson cannot supersede itself.\", since a blank successor reads as the lesson itself.", "\"Name the lesson that replaces this one.\"", "\"Say why this lesson is being archived.\", as a supersede is treated as an archive.", "Nothing: the move is allowed and the successor can be added later."]'::jsonb, 1, 'A superseded lesson has a successor, and naming it keeps the trail intact. "A lesson cannot supersede itself." is the refusal when a lesson names itself.'),
  ('riskchange', 'advanced', 'final', null, 27, 'A lesson''s use in management of change is logged without saying which change it went into. What does the engine say?', '["\"Name the change record this lesson went into.\"", "\"Name the risk.\"", "\"Pick what this lesson was applied to.\"", "Nothing: a change register target needs only its target type to be recorded."]'::jsonb, 0, 'Both Suite register targets carry a real key. A risk register target must name the risk and a change register target must name the change record, so a reader at either end can follow the trail.'),
  ('riskchange', 'advanced', 'final', null, 28, 'An application arrives with an outcome the register does not know. What does the engine ask?', '["\"Pick what this lesson was applied to.\"", "\"Say why it was not adopted.\"", "\"Was the lesson adopted, adapted, or rejected?\"", "Nothing: an unknown outcome is recorded as \"Other\"."]'::jsonb, 2, 'The refusal is a question, and it lists the three outcomes the engine knows. "Other" is one of the eight target types and has nothing to do with outcomes.'),
  ('riskchange', 'advanced', 'final', null, 29, 'A lesson changed a site procedure, and the person logging it leaves the reference blank. Which sentence comes back?', '["\"Name what changed (the procedure, the course, the standard) so somebody can go and look at it.\"", "\"Name the change record this lesson went into.\"", "\"Pick what this lesson was applied to.\"", "Nothing: a procedure lives outside the Suite, so no reference can be checked and none is asked for."]'::jsonb, 0, 'A procedure, a course or a standard lives outside the Suite, so the engine asks for a reference a person can follow. The target type is given here, which is why the question about what it was applied to does not arise.'),
  ('riskchange', 'advanced', 'final', null, 30, 'ON-01''s AA-03 was a "Training" application with the outcome "Rejected". What is "Rejected" in that sentence?', '["A lesson status, which moves ON-01 out of \"Published\".", "A comment status, carried over from the review of the lesson.", "An application outcome, which says nothing about the lesson''s own status.", "A change stage, recorded against the training course."]'::jsonb, 2, '"Rejected" is a comment status, a change stage and an application outcome in this course. Here it is an outcome recorded against one target, and ON-01 is still "Published".'),
  ('riskchange', 'advanced', 'final', null, 31, 'ON-10 is "Published" with its review date on 2026-11-01. Which review reading does it carry on 2026-10-01?', '["\"review due soon\", as the lead is 30 days and both ends are counted in it.", "\"review due soon\", since every review in the next month is inside the lead.", "Neither overdue nor due soon, being 31 days away.", "\"review overdue\", since it falls after the lead."]'::jsonb, 2, 'Counting both ends, the lead on 2026-10-01 runs to 2026-10-31 and stops there. ON-10 is one day beyond it, so it reads neither.'),
  ('riskchange', 'advanced', 'final', null, 32, 'An "Embedded" lesson had its review date on 2026-09-30. On 2026-10-01, is it overdue, due soon, or both?', '["Due soon and not overdue, since a lesson has a day of grace after its date.", "Overdue, one day past its date, and no longer due soon.", "Overdue and due soon together.", "Neither, since the review date is behind it."]'::jsonb, 1, 'The edge table''s row at -1 days, a review due 2026-09-30, reads overdue yes and due soon no. An embedded lesson is visible, so it carries a review status.'),
  ('riskchange', 'advanced', 'final', null, 33, 'The ONNE summary reads live 8 and visible 5. Which lessons are outside the live count?', '["ON-05, ON-06 and ON-07, which are not visible.", "ON-03 and ON-04, which nobody has applied.", "ON-06 and ON-07, which lack substance.", "ON-08 and ON-09."]'::jsonb, 3, 'Live is "Draft", "Submitted", "Validated", "Published" and "Embedded". ON-08 is "Archived" and ON-09 is "Superseded", so the ten lessons less those two give 8. Visible 5 is the four "Published" lessons and the one "Embedded".'),
  ('riskchange', 'advanced', 'final', null, 34, 'In the ONNE summary, which lessons are awaitingValidation 1 and drafts 1?', '["ON-05 awaiting validation, ON-07 the draft.", "ON-06 awaiting validation, ON-07 the draft.", "ON-06 awaiting validation, ON-05 the draft.", "ON-07 awaiting validation, ON-06 the draft."]'::jsonb, 1, 'ON-06 is "Submitted" and waits for somebody other than its author to validate it. ON-07 is the "Draft". ON-05 is already "Validated" and waits to be published.'),
  ('riskchange', 'advanced', 'final', null, 35, 'What does the digest hold happens when an invalid as-of date reaches daysUntil?', '["It refuses with a reason the user can act on, in the usual refusal shape.", "It answers NaN, and every date rule then reads as not due.", "It falls back to the machine clock and answers for today.", "It answers 0, so every date reads as due on the as-of date."]'::jsonb, 1, 'A comparison on NaN is false either way, so every date rule reads as not due. The digest lists this among the held items; nothing in this course passes an invalid date.'),
  ('riskchange', 'advanced', 'final', null, 36, 'How many golden cases does the digest measure across the five files this course reads, and in how many time zones does the gate replay each?', '["1037, in one time zone, the one the digest was built in.", "345, the lessonsLearned file, in five time zones.", "1037, in two time zones, Lagos and UTC.", "1037, and every case is replayed in five time zones."]'::jsonb, 3, 'The five files hold 77, 140, 291, 184 and 345 cases. The other five assurance golden files belong to Compliance, Audit & Quality.'),
  ('riskchange', 'advanced', 'final', null, 37, 'How many held items does the digest list, and how is each one taught?', '["Four, each an owner decision taken on 2026-09-18 and held in the engine.", "Nine, each graded in a capstone field so that a learner proves the limit.", "Five, one for each golden file.", "Nine, each taught as a stated limit and graded nowhere."]'::jsonb, 3, 'A held item is a rule the engines state that no owner has decided, or a behaviour that is a limit of the engine, and the digest lists nine. Each is taught as a stated limit and graded nowhere. The owner decisions are the other list: rules an owner has decided, which an engine must follow.'),
  ('riskchange', 'advanced', 'final', null, 38, 'On 2026-10-01 the ONNE summary reads lessonsUnapplied 2. Which lessons are they?', '["ON-06 and ON-07, the two lessons that lack substance.", "ON-03 and ON-04, the visible lessons with no adoption or adaptation.", "ON-08 and ON-09, the two lessons out of use on the register.", "ON-03 and ON-05, the visible lessons whose reviews are inside the lead."]'::jsonb, 1, 'ON-03''s one application is a rejection and ON-04 has none, which is also why they lead lessonByAttention. ON-05 is not visible, and ON-06 to ON-09 are not counted because they are not visible either.'),
  ('riskchange', 'advanced', 'final', null, 39, 'Today, what must an Emergency change have signed to go into Implementation, and what before it may close?', '["Every approval level signed to go in, as for a Permanent change, and nothing further to close.", "Its first level to go in, and nothing more to close once its ratification window has passed.", "Its first approval level signed with nobody rejecting to go in, and every level signed before it can close.", "No signature to go in, being an emergency, and its first level signed later to close."]'::jsonb, 2, 'The emergency route is owner policy: reduced authority up front so a hazard can be dealt with, full review after the event. The gate into Implementation asks for level 1 and no rejection. The gate into Closed asks for every level, and until they sign the change reads "Awaiting ratification", or "Ratification overdue" once its window has passed.'),
  ('riskchange', 'advanced', 'final', null, 40, 'Agreement between an engine and its independent oracle proves what, and leaves what open?', '["That the engine does what the stated rule says on those inputs; whether the rule is right stays open.", "That the rule is the right rule, since two methods reached it by different routes.", "That the held items are closed, since both methods agree on them.", "That the app displays what the engine computes."]'::jsonb, 0, 'Agreement shows two methods reading the stated rule the same way on those inputs. Whether a rule is right is for the owner to decide, and the digest keeps the rules an owner has decided apart from the held items nobody has ruled on. A limit both methods share is still a limit, and what the app shows is the app''s part.'),
  ('riskchange', 'advanced', 'final', null, 41, 'ON-01''s application into the risk register: on which date, with which outcome, naming which risk?', '["2026-05-02, \"Adopted\", naming OB-07, Pump house flooded in the rainy season.", "2026-07-14, \"Adapted\", naming OB-07, Pump house flooded in the rainy season, the date ON-01 was last applied.", "2026-05-02, \"Adopted\", naming ES-06, Revised operating procedure for glycol regeneration.", "2026-03-12, \"Adopted\", naming OB-07."]'::jsonb, 0, '2026-07-14 is AA-02, ON-01''s adaptation into a procedure, and 2026-03-12 is ON-01''s event date. ES-06 is the change ON-02 was applied into.'),
  ('riskchange', 'advanced', 'final', null, 42, 'Which owner decision taken on 2026-09-18 reaches both the change register and peer review?', '["Q9, emergency change authority and the ratification window, which also sets review due dates.", "Q10, validation by typed name, which also governs who verifies a comment.", "D1, segregation of duties.", "Q3, fractional levels unscored."]'::jsonb, 2, 'D1 holds segregation of duties on change approvals and, from ASC-0, on peer review. In peer review the engine enforces it now, and the app and database follow with the Suite pull request that ships ASC-0.');
